"""Mapbox Vector Tiles generated by PostGIS (``ST_AsMVT``).

The map can show every hotspot, event and burned area at any zoom without the
browser downloading whole tables: each tile request is one indexed spatial query,
and geometry is clipped and quantised to the tile by the database.
"""

from __future__ import annotations

import datetime as dt
from typing import Annotated, Any, Literal

from fastapi import APIRouter, HTTPException, Query, Response, status

from narsat.api.deps import ConnDep, ensure_utc

router = APIRouter(tags=["tiles"])

MVT = "application/vnd.mapbox-vector-tile"

_ENVELOPE = "ST_TileEnvelope(%(z)s, %(x)s, %(y)s)"

#: Below this zoom several detections share one screen pixel; the tile then carries one
#: detection per pixel-sized cell (the one with the highest radiative power) instead of
#: every row. A whole-region tile of a busy season stays a few hundred kilobytes
#: instead of tens of megabytes, and the picture on screen is the same.
THIN_BELOW_ZOOM = 8
WEB_MERCATOR_WIDTH_M = 40_075_016.68557849
CELLS_PER_TILE = 512

_HOTSPOT_CANDIDATES = f"""
        WITH tile AS (SELECT {_ENVELOPE} AS box),
        candidates AS (
            SELECT ST_Transform(h.geom, 3857) AS geom_3857, h.hotspot_id, h.confidence_level,
                   h.instrument, h.frp_mw, h.acq_ts, h.event_id
            FROM hotspot h, tile
            WHERE h.geom && ST_Transform(tile.box, 4326)
              AND NOT h.is_static_source
              AND (%(start)s::timestamptz IS NULL OR h.acq_ts >= %(start)s)
              AND (%(end)s::timestamptz IS NULL OR h.acq_ts <= %(end)s)
        ),
"""
_HOTSPOT_THINNING = """
        thinned AS (
            SELECT DISTINCT ON (ST_SnapToGrid(c.geom_3857, %(cell)s)) c.*
            FROM candidates c
            ORDER BY ST_SnapToGrid(c.geom_3857, %(cell)s), c.frp_mw DESC NULLS LAST, c.acq_ts DESC
        ),
"""
_HOTSPOT_FEATURES = """
        features AS (
            SELECT ST_AsMVTGeom(c.geom_3857, tile.box, 4096, 64, true) AS geom,
                   c.hotspot_id::text AS id, c.confidence_level, c.instrument,
                   round(c.frp_mw::numeric, 1)::float8 AS frp_mw,
                   extract(epoch FROM c.acq_ts)::bigint AS acq_epoch,
                   c.event_id::text AS event_id
            FROM {source} c, tile
        )
        SELECT ST_AsMVT(features, 'hotspots', 4096, 'geom') AS tile FROM features
"""

_QUERIES: dict[str, str] = {
    "hotspots": _HOTSPOT_CANDIDATES + _HOTSPOT_FEATURES.format(source="candidates"),
    "hotspots_thinned": (
        _HOTSPOT_CANDIDATES + _HOTSPOT_THINNING + _HOTSPOT_FEATURES.format(source="thinned")
    ),
    "events": f"""
        WITH tile AS (SELECT {_ENVELOPE} AS box),
        features AS (
            SELECT ST_AsMVTGeom(ST_Transform(e.hull, 3857), tile.box, 4096, 64, true) AS geom,
                   e.event_id::text AS id, e.status, e.mapping_status, e.n_hotspots,
                   round(e.hull_area_ha::numeric, 0)::float8 AS hull_area_ha,
                   extract(epoch FROM e.first_seen)::bigint AS first_epoch,
                   extract(epoch FROM e.last_seen)::bigint AS last_epoch
            FROM fire_event e, tile
            WHERE e.hull && ST_Transform(tile.box, 4326)
              AND e.status IN ('active', 'cooling', 'closed')
              AND (%(start)s::timestamptz IS NULL OR e.last_seen >= %(start)s)
              AND (%(end)s::timestamptz IS NULL OR e.first_seen <= %(end)s)
        )
        SELECT ST_AsMVT(features, 'events', 4096, 'geom') AS tile FROM features
    """,
    "burned_areas": f"""
        WITH tile AS (SELECT {_ENVELOPE} AS box),
        features AS (
            SELECT ST_AsMVTGeom(ST_Transform(b.geom, 3857), tile.box, 4096, 64, true) AS geom,
                   b.ba_id::text AS id, b.event_id::text AS event_id, b.method, b.qa_status,
                   round(b.area_ha::numeric, 1)::float8 AS area_ha,
                   extract(epoch FROM b.post_datetime)::bigint AS post_epoch
            FROM burned_area b
            JOIN fire_event e ON e.event_id = b.event_id, tile
            WHERE b.geom && ST_Transform(tile.box, 4326)
              AND b.qa_status <> 'rejected'
              AND (%(method)s::text IS NULL OR b.method = %(method)s)
              AND (%(start)s::timestamptz IS NULL OR e.last_seen >= %(start)s)
              AND (%(end)s::timestamptz IS NULL OR e.first_seen <= %(end)s)
        )
        SELECT ST_AsMVT(features, 'burned_areas', 4096, 'geom') AS tile FROM features
    """,
}


@router.get(
    "/tiles/{layer}/{z}/{x}/{y}.mvt",
    response_class=Response,
    responses={200: {"content": {MVT: {}}}, 204: {"description": "Empty tile"}},
)
async def vector_tile(
    layer: Literal["hotspots", "events", "burned_areas"],
    z: int,
    x: int,
    y: int,
    conn: ConnDep,
    start: Annotated[dt.datetime | None, Query()] = None,
    end: Annotated[dt.datetime | None, Query()] = None,
    method: Annotated[Literal["dnbr", "model"] | None, Query()] = None,
) -> Response:
    """One vector tile of a layer, optionally limited to a period."""
    if not (0 <= z <= 22 and 0 <= x < 2**z and 0 <= y < 2**z):
        raise HTTPException(status.HTTP_404_NOT_FOUND, "tile outside the XYZ pyramid")
    params: dict[str, Any] = {
        "z": z, "x": x, "y": y, "start": ensure_utc(start), "end": ensure_utc(end),
        "method": method, "cell": WEB_MERCATOR_WIDTH_M / 2**z / CELLS_PER_TILE,
    }  # fmt: skip
    thin = layer == "hotspots" and z < THIN_BELOW_ZOOM
    query = _QUERIES["hotspots_thinned" if thin else layer]
    row = await (await conn.execute(query, params)).fetchone()
    tile = bytes(row["tile"]) if row and row["tile"] else b""
    headers = {"Cache-Control": "public, max-age=60"}
    if not tile:
        return Response(status_code=status.HTTP_204_NO_CONTENT, headers=headers)
    return Response(tile, media_type=MVT, headers=headers)
